package io.pocketpad.protocol

import org.json.JSONObject
import java.io.File
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertFalse
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
private fun ByteArray.hex() = joinToString("") { "%02x".format(it) }

/** Checks this implementation against protocol/testvectors/v1.json, generated by the Go receiver. */
class VectorsTest {
    private val v = JSONObject(File(System.getProperty("vectors") ?: "../../protocol/testvectors/v1.json").readText())

    @Test fun version() = assertEquals(Wire.VERSION, v.getInt("version"))

    @Test fun axisAndTrigger() {
        val axis = v.getJSONArray("axis")
        for (i in 0 until axis.length()) {
            val o = axis.getJSONObject(i)
            val f = o.getDouble("value").toFloat()
            assertEquals(o.getInt("wire"), Codec.encodeAxis(f), "axis $f")
        }
        val trig = v.getJSONArray("trigger")
        for (i in 0 until trig.length()) {
            val o = trig.getJSONObject(i)
            val f = o.getDouble("value").toFloat()
            assertEquals(o.getInt("wire"), Codec.encodeTrigger(f), "trigger $f")
        }
    }

    @Test fun seqNewerVectors() {
        val a = v.getJSONArray("seqNewer")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i)
            assertEquals(o.getBoolean("newer"), seqNewer(o.getInt("a"), o.getInt("b")), o.toString())
        }
    }

    @Test fun stateEncodeDecode() {
        val a = v.getJSONArray("state")
        val buf = ByteArray(Wire.STATE_SIZE)
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i)
            Codec.putStateRaw(
                buf, o.getInt("seq"), o.getInt("buttons"), o.getInt("dpad"), o.getInt("flags"),
                o.getInt("lx"), o.getInt("ly"), o.getInt("rx"), o.getInt("ry"), o.getInt("lt"), o.getInt("rt"),
            )
            assertEquals(o.getString("hex"), buf.hex(), o.getString("name"))
            val s = ControllerState()
            val flags = Codec.decodeState(hex(o.getString("hex")), Wire.STATE_SIZE, s)
            assertEquals(o.getInt("flags"), flags)
            assertEquals(o.getInt("buttons"), s.buttons)
            assertEquals(o.getInt("dpad"), s.dpad)
            assertEquals(Codec.decodeAxis(o.getInt("lx")), s.lx)
            assertEquals(Codec.decodeTrigger(o.getInt("rt")), s.rt)
        }
    }

    @Test fun normalizedStateMatchesGo() {
        // The "half sticks" vector was produced from normalized values in Go.
        val s = ControllerState().apply {
            lx = 0.5f; ly = -0.5f; rx = -0.25f; ry = 0.25f; lt = 0.5f; rt = 0.25f
            buttons = Buttons.LS or Buttons.RS; dpad = DPad.DOWN
        }
        val buf = ByteArray(Wire.STATE_SIZE)
        Codec.putState(buf, 40000, s, 0)
        val want = (0 until v.getJSONArray("state").length()).map { v.getJSONArray("state").getJSONObject(it) }
            .first { it.getString("name") == "half sticks" }.getString("hex")
        assertEquals(want, buf.hex())
    }

    @Test fun invalidPackets() {
        val a = v.getJSONArray("invalid")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i)
            val b = hex(o.getString("hex"))
            val e = assertFailsWith<ProtocolException>(o.getString("name")) { Codec.checkDatagram(b, b.size) }
            assertEquals(o.getString("error"), e.kind, o.getString("name"))
        }
    }

    @Test fun pairing() {
        val p = v.getJSONObject("pairing")
        val secret = hex(p.getString("secretHex"))
        assertEquals(p.getString("code"), Pairing.format(secret))
        assertContentEquals(secret, Pairing.parse(p.getString("code")))
        assertContentEquals(secret, Pairing.parse(p.getString("code").lowercase().replace("0", "o").replace("-", " ")))
        assertContentEquals(hex(p.getString("pairKeyHex")), Pairing.pairKey(secret))
        assertNull(Pairing.parse("UUUU"))
        assertNull(Pairing.parse(p.getString("code") + "0"))
    }

    @Test fun handshake() {
        val h = v.getJSONObject("handshake")
        val pairKey = hex(v.getJSONObject("pairing").getString("pairKeyHex"))
        val cn = hex(h.getString("clientNonceHex"))
        val deviceId = h.getString("deviceId").toULong().toLong()

        // HELLO: our encoding and tag match byte for byte.
        val hello = ByteArray(Wire.HELLO_SIZE + Wire.HANDSHAKE_TAG_SIZE)
        Codec.putHello(hello, deviceId, cn, Wire.CAP_RUMBLE or Wire.CAP_BATTERY or Wire.CAP_LATENCY_ECHO, h.getString("deviceName"))
        System.arraycopy(Handshake.tag(pairKey, hello, Wire.HELLO_SIZE, ByteArray(0)), 0, hello, Wire.HELLO_SIZE, Wire.HANDSHAKE_TAG_SIZE)
        assertEquals(h.getString("helloHex"), hello.hex())

        // WELCOME: verify and decode.
        val welcome = hex(h.getString("welcomeHex"))
        assertEquals(Wire.TYPE_WELCOME, Codec.checkHeader(welcome, welcome.size))
        assertTrue(Handshake.verify(pairKey, welcome, welcome.size, cn))
        assertFalse(Handshake.verify(pairKey, welcome, welcome.size, ByteArray(16)))
        val w = Codec.decodeWelcome(welcome)
        assertEquals(h.getLong("sessionId").toInt(), w.sessionId)
        assertEquals(500, w.heartbeatMs)
        assertEquals(250, w.maxRateHz)
        assertContentEquals(hex(h.getString("serverNonceHex")), w.serverNonce)

        val keys = Handshake.deriveSessionKeys(pairKey, deviceId, cn, w.serverNonce, w.sessionId)
        assertEquals(h.getString("c2sKeyHex"), keys.clientToServer.hex())
        assertEquals(h.getString("s2cKeyHex"), keys.serverToClient.hex())
    }

    @Test fun sessionPackets() {
        val h = v.getJSONObject("handshake")
        val c2s = hex(h.getString("c2sKeyHex"))
        val s2c = hex(h.getString("s2cKeyHex"))
        val a = v.getJSONArray("session")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i)
            val pkt = hex(o.getString("hex"))
            val key = if (o.getString("direction") == "c2s") c2s else s2c
            val ext = o.getLong("ext")
            Codec.checkDatagram(pkt, pkt.size)
            assertTrue(SessionMac(key).verify(pkt, pkt.size, ext), o.getString("name"))
            // Re-seal and compare: tags are deterministic.
            val copy = pkt.copyOf()
            SessionMac(key).seal(copy, pkt.size - Wire.TAG_SIZE, ext)
            assertContentEquals(pkt, copy, o.getString("name"))
        }
        // The receiver-side opener accepts the s2c stream in order and rejects replays.
        val opener = Opener(s2c)
        val hb = hex(a.getJSONObject(3).getString("hex"))
        val rumble = hex(a.getJSONObject(4).getString("hex"))
        opener.open(hb, hb.size)
        opener.open(rumble, rumble.size)
        assertEquals(Wire.TYPE_RUMBLE, Codec.typeOf(rumble))
        assertEquals(0xFFFF, Codec.rumbleLeft(rumble))
        assertEquals(750, Codec.rumbleDurationMs(rumble))
        assertEquals("stale", assertFailsWith<ProtocolException> { opener.open(hb, hb.size) }.kind)
    }
}

class ProtocolTest {
    @Test fun replayWindowWraps() {
        val w = ReplayWindow()
        for (i in 0L until 70000L) {
            val ext = w.estimate((i and 0xFFFF).toInt())
            assertEquals(i, ext)
            w.accept(ext)
            assertEquals(-1, w.estimate((i and 0xFFFF).toInt()))
        }
    }

    @Test fun sealOpenAcrossWraparound() {
        val key = ByteArray(32) { it.toByte() }
        val sealer = Sealer(key)
        val opener = Opener(key)
        val buf = ByteArray(Wire.MAX_DATAGRAM)
        val s = ControllerState().apply { buttons = Buttons.A }
        var captured: ByteArray? = null
        repeat(65546) { i ->
            val ext = sealer.next()
            Codec.putState(buf, (ext and 0xFFFF).toInt(), s, 0)
            val n = sealer.seal(buf, Wire.STATE_SIZE, ext)
            if (i == 20) captured = buf.copyOf(n)
            opener.open(buf, n)
        }
        val c = assertNotNull(captured)
        assertEquals("auth", assertFailsWith<ProtocolException> { opener.open(c, c.size) }.kind)
    }

    @Test fun truncateUtf8() {
        assertEquals("Pixel 8 Pro Controller ", String(Codec.truncateUtf8("Pixel 8 Pro Controller —x", 24)))
        assertEquals("Pixel 8 Pro Controlle—", String(Codec.truncateUtf8("Pixel 8 Pro Controlle—x", 24)))
    }

    @Test fun dpad() {
        for (d in 0..8) assertEquals(d, DPad.from(DPad.up(d), DPad.down(d), DPad.left(d), DPad.right(d)))
    }
}
